from flask import Flask, redirect, url_for, session

app = Flask(__name__)

# Secret key for session management
app.secret_key = 'your_secret_key'

@app.route('/')
def index():
    # Check if the user is logged in
    if 'username' in session:
        # If the user is an admin, redirect to the admin page
        if session.get('is_admin'):
            return redirect(url_for('admin'))
        else:
            return redirect(url_for('user'))
    else:
        # Redirect to login page if not logged in
        return redirect(url_for('login'))

@app.route('/login')
def login():
    # Simulate a login process (in practice, you'd have authentication logic here)
    # For demonstration purposes, let's assume the user logs in with these details
    session['username'] = 'example_user'
    session['is_admin'] = True  # Change to False if the user is not an admin

    return "Logged in as: {}".format(session['username'])

@app.route('/user')
def user():
    if 'username' in session:
        return f"Welcome, {session['username']}! You are a regular user."
    else:
        return redirect(url_for('login'))

@app.route('/admin')
def admin():
    if 'username' in session and session.get('is_admin'):
        return f"Welcome, {session['username']}! You have admin privileges."
    else:
        return redirect(url_for('login'))

if __name__ == '__main__':
