int main() {
    const char *filename = "example.txt";
    int file_descriptor;

    // Open the file with flags: O_WRONLY | O_CREAT | O_TRUNC | O_EXCL
    // Set mode to 0644, which sets read and write permissions for owner,
    // and read-only for group and others.
    file_descriptor = open(filename, O_WRONLY | O_CREAT | O_TRUNC | O_EXCL, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);

    if (file_descriptor == -1) {
        // If open() fails, print the error message
        perror("Error opening file");
        return 1;
    }

