    va_list args;
    va_start(args, format);
    int length = vsnprintf(NULL, 0, format, args) + 1; // +1 for null terminator
    va_end(args);

    if (length <= 0) {
        return NULL;
    }

    char *buffer = (char *)malloc(length * sizeof(char));
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Format the string into the buffer
    va_start(args, format);
    vsnprintf(buffer, length, format, args);
    va_end(args);

    return buffer;
}

int main() {
    // Construct a command using our custom print function
    char *command = print("ls -l %s", "directory_name"); // Replace 'directory_name' with desired directory

    if (command) {
        printf("Executing command: %s\n", command);

        // Execute the constructed command using system()
        int result = system(command);

        if (result == -1) {
            fprintf(stderr, "Command execution failed\n");
        } else {
            printf("Command executed successfully with status code: %d\n", result);
        }

        // Free the memory allocated for the command string
        free(command);
    }

    return 0;
}
```

### Explanation:

1. **`print` Function**: This function mimics `printf`, constructing a formatted string using variable arguments (`...`). It first calculates the required buffer size and then allocates memory to store the formatted string.

2. **Memory Management**: The program dynamically allocates memory for the command string, which is later freed after use to prevent memory leaks.

3. **System Command Execution**: The constructed command string (e.g., `ls -l directory_name`) is executed using the `system` function.

4. **Error Handling**: Basic error handling is provided for both memory allocation and system command execution failures.

Remember to replace `"directory_name"` with an actual directory path you wish to list, or modify it further as per your needs. This code should be compiled using a C compiler like GCC:

```sh
gcc -o execute_ls execute_ls.c
./execute_ls
```

Ensure that the environment where this program is executed has the appropriate permissions and access to use `system` commands securely.']

