['Below is a C code snippet that demonstrates how you can use the `system` function to execute the `ls` command. This example also uses a simple implementation of a custom `print` function with variadic arguments to construct the command string dynamically.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>

// Custom print function similar to sprintf, but stores result in a buffer
int my_print(char *buffer, size_t buf_size, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Use vsnprintf for safer formatting with variadic arguments
    int written = vsnprintf(buffer, buf_size, format, args);

    // Check if the buffer was large enough to hold the formatted string
    if (written < 0 || written >= buf_size) {
        fprintf(stderr, "Error: Buffer too small\n");
        va_end(args);
        return -1;
    }

    va_end(args);
    return written; // Return number of characters written, not including null terminator
}

int main() {
    char command[256];  // Buffer to hold the command string

    // Use the custom print function to construct the ls command with options
    if (my_print(command, sizeof(command), "ls -l %s", "") < 0) {
        return EXIT_FAILURE;
    }

    printf("Executing: %s\n", command);

    // Execute the constructed command using system()
    int status = system(command);

    if (status == -1) {
        fprintf(stderr, "Error executing command\n");
        return EXIT_FAILURE;
    }

    return 0;
}
```

### Key Points:

- **`my_print` Function**: This function mimics the behavior of `sprintf`, but it uses a buffer to store formatted strings. It takes a variable number of arguments using `va_list`.

